import hashlib,json,os,pathlib,re,stat
KNOWN=json.loads(KNOWN_JSON)
fields=dict(line.split(':',1) for line in pathlib.Path('/proc/self/status').read_text().splitlines() if ':' in line)
assert os.getuid()==65532 and fields['NoNewPrivs'].strip()=='1'
assert all(int(fields[n].strip(),16)==0 for n in ('CapEff','CapPrm','CapBnd'))
records={}
aliases=[]
for name,sha in sorted(KNOWN.items()):
 p=pathlib.Path(name);before=p.lstat();target=p.resolve(strict=True);info=target.lstat()
 assert (str(target).startswith('/usr/bin/') or str(target).startswith('/usr/lib/')) and stat.S_ISREG(info.st_mode)
 assert 64<=info.st_size<=64*1024*1024
 item={'path':str(target),'bytes':info.st_size,'sha256':sha,'source':'known-program-or-ldd'}
 if str(target) in records:assert records[str(target)]==item
 records[str(target)]=item
 aliases.append({'originalPath':name,'originalMode':oct(stat.S_IMODE(before.st_mode)),'wasSymlink':stat.S_ISLNK(before.st_mode),'resolvedPath':str(target),'expectedSha256':sha})
module_dir=pathlib.Path('/usr/lib/python3.13/lib-dynload');module_bytes=0;modules=[]
for p in sorted(module_dir.glob('*.so')):
 assert p.parent==module_dir and re.fullmatch(r'[A-Za-z0-9_.+\-]+[.]so',p.name)
 info=p.lstat();assert stat.S_ISREG(info.st_mode) and not p.is_symlink() and 64<=info.st_size<=8*1024*1024
 module_bytes+=info.st_size;assert module_bytes<=64*1024*1024 and len(modules)<128
 digest=hashlib.sha256()
 with p.open('rb') as stream:
  assert os.fstat(stream.fileno()).st_size==info.st_size
  for chunk in iter(lambda:stream.read(65536),b''):digest.update(chunk)
 item={'path':str(p),'bytes':info.st_size,'sha256':digest.hexdigest(),'source':'direct-regular-python-module'}
 assert str(p) not in records;records[str(p)]=item;modules.append(str(p))
assert modules and len(records)<=192 and sum(r['bytes'] for r in records.values())<=256*1024*1024
result={'status':'metadata-only','image':IMAGE,'priorMetadataSha256':PRIOR_SHA,'knownAliasCount':len(aliases),'knownAliases':aliases,'files':sorted(records.values(),key=lambda r:r['path']),'pythonModuleCount':len(modules),'pythonModuleBytes':module_bytes,'totalBytes':sum(r['bytes'] for r in records.values()),'filesReadForHashing':modules,'targetModulesImported':False}
